import os, sys, glob
REV = int(sys.argv[1]); ENV = sys.argv[2]; HOST = sys.argv[3]
CFG = '/app/config'; HIST = '/app/config-history'
revs = sorted(int(d[1:]) for d in os.listdir(HIST) if d.startswith('r'))

def getfile(abspath):
    rel = os.path.relpath(abspath, CFG)
    for r in revs:
        if r > REV:
            p = '%s/r%04d/prev/%s' % (HIST, r, rel)
            if os.path.exists(p):
                return open(p).read()
    return open(abspath).read()

def read(path, name, state, in_include=False):
    section = None
    for line in getfile(path).splitlines() if path.startswith(CFG) else open(path).read().splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('[') and line.endswith(']'):
            section = line[1:-1].strip()
            continue
        if '=' not in line:
            continue
        k, v = [x.strip() for x in line.split('=', 1)]
        if k == 'include':
            if section is not None:
                continue
            p = v.replace('${env}', ENV).replace('${host}', HOST)
            p = os.path.normpath(os.path.join(os.path.dirname(path), p))
            read(p, name, state)
            continue
        if in_include or path.startswith(CFG):
            if section is not None and section != name:
                continue
        state[k] = v

for svc in sorted(os.listdir('/app/services')):
    st = {}
    read('/app/services/%s/service.conf' % svc, None, st)
    # name from conf
    n = st.get('name', svc)
    st = {}
    # re-read with name for section matching
    def rd(path):
        read(path, n, st)
    rd('/app/services/%s/service.conf' % svc)
    en = st.get('enabled', 'true')
    try:
        main = int(st['port_base']) + int(st.get('port_offset', 0))
    except Exception:
        main = None
    print(n, 'enabled=' + en, 'main=', main, 'admin=', st.get('admin_port'))
